+func TestTaskGraphApprovalRollsBackEveryPrecommitFailure(t *testing.T) {
+	for _, point := range []TaskGraphApprovalFaultPoint{
+		FaultTaskGraphAfterWorkflow, FaultTaskGraphAfterBinding, FaultTaskGraphAfterEnqueue,
